export function featureMarketSummary({now=Date.now()}={}){
 const marketStatus=[...marketStates.values()].filter(s=>s.basis==='provider_market_state'&&['open','closed'].includes(s.state)&&['NASDAQ','NYSE','NYSEARCA','AMEX'].includes(s.exchange)&&Number.isFinite(Date.parse(s.asOf))&&now-Date.parse(s.asOf)>=0&&now-Date.parse(s.asOf)<=60000).sort((a,b)=>Date.parse(b.asOf)-Date.parse(a.asOf))[0]??null;
 const benchmark=marketScanSnapshot.find(f=>f.symbol==='SPY');
 const opportunities=benchmark?rankOpportunities(marketScanSnapshot.filter(f=>f.symbol!=='SPY'),{benchmark,now}).map(a=>({symbol:a.symbol,asOf:a.asOf,score:a.score,scenario:a.scenario,source:a.scenario.sources})):[];
 return {marketStatus,opportunities};
}
export function dashboardValues(){if(!state)return null;const l=calc();const valuation=calculatePortfolio(state.events,{quotes:Object.fromEntries([...feeds].map(([symbol,feed])=>[symbol,quoteFromCandles(feed)])),fx:fxFeed,allowMargin:state.preferences.allowMargin,method:state.preferences.costMethod});return {loaded:true,error,valuation:structuredClone(valuation),preferences:{...featurePreferences},marketStatus:[...marketStates.values()].sort((a,b)=>(b.asOf||'').localeCompare(a.asOf||''))[0]??null,positionEntries:l.positions.filter(p=>Number(p.quantity)>0).map(({symbol,quantity})=>({symbol,quantity})),watchlistEntries:[...state.watchlist],planEntries:state.journal.slice(0,3).map(({id,symbol,status})=>({id,symbol,status})),cash:money(l.cash.USD)+' · '+money(l.cash.EUR,'EUR'),positions:l.positions.map(p=>p.symbol+' '+p.quantity).join(' · ')||'Nog geen open posities.',watchlist:state.watchlist.join(' · ')||'Nog geen aandelen toegevoegd.',plans:state.journal.slice(0,3).map(j=>j.symbol+' · '+optionLabel(j.status)).join(' / ')||'Nog geen handelsplannen.'};}

