  panel.querySelector('#scan-table').innerHTML=rows.length?table([mt('ticker'),mt('decision'),mt('asOf'),mt('trend'),'RSI','MACD',mt('volume'),mt('strength'),mt('volatility')],rows.map(({feed:f,a})=>`<tr><td><button class="chip" type="button" data-select-candidate="${esc(f.symbol)}" aria-pressed="${selected===f.symbol}">${esc(f.symbol)}</button></td><td>${mt(a.status==='scenario'?'scenario':'wait')}</td><td>${esc(a.asOf||f.asOf)}</td><td>${esc(qualityLabel(a.trend))}</td><td>${a.indicators?.rsi?.toFixed(1)||'—'}</td><td>${a.indicators?.macd?.histogram?.toFixed(3)||'—'}</td><td>${a.indicators?.relativeVolume?.toFixed(2)||'—'}</td><td>${a.comparison?.comparable?(a.comparison.relativeStrength*100).toFixed(2)+'%':mt('notComparable')}</td><td>${a.volatility?.atr?.toFixed(3)||'—'}</td></tr>`)):'';
