 file.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;const session=readEpoch;try{if(f.size>200000)throw Error('Maximaal 200 KB');const text=await f.text();if(session!==readEpoch||!state)return;mappingUpload={text,session};buildMapping();}catch(err){message('Bestand niet geladen: '+err.message);}});
